import Foundation
import CoreGraphics
import CoreImage
import CoreVideo
import ImageIO

/// Runs the generated byte-for-byte production recognition and hero/group
/// implementation on every frozen COCO source. No expected hero is assigned.
@main
enum SubjectFusionValidation {
    struct Failure: Error { let message: String }
    struct Source: Decodable {
        let id: Int
        let file_name: String
        let width: Int
        let height: Int
    }
    struct GroundTruth: Decodable { let images: [Source] }

    static func box(_ rect: CGRect) -> [Double] {
        [Double(rect.minX), Double(rect.minY), Double(rect.width), Double(rect.height)]
    }

    static func group(_ category: NeuralSubjectCategory) -> String {
        switch category {
        case .human: return "people"
        case .face: return "faces"
        case .animal: return "animals"
        case .foregroundObject: return "objects"
        case .general: return "scenery"
        }
    }

    static func candidate(_ value: NeuralSubjectCandidate, rank: Int) throws -> [String: Any] {
        guard [value.boundingBox.minX, value.boundingBox.minY, value.boundingBox.width,
               value.boundingBox.height].allSatisfy(\.isFinite),
              value.boundingBox.width > 0, value.boundingBox.height > 0,
              value.confidence.isFinite, value.prominenceScore.isFinite else {
            throw Failure(message: "Production fusion returned a non-finite candidate")
        }
        return ["rank": rank, "label": value.label, "category": value.category.rawValue,
            "evaluationGroup": group(value.category), "confidence": Double(value.confidence),
            "prominence": value.prominenceScore, "box": box(value.boundingBox),
            "isGroup": value.isGroup, "faceCount": value.faceBounds.count,
            "faceBounds": value.faceBounds.map(box), "companionBounds": value.companionBounds.map(box),
            "eyePosition": value.eyePosition.map { [Double($0.x), Double($0.y)] as Any } ?? NSNull(),
            "trackingPoint": value.trackingPoint.map { [Double($0.x), Double($0.y)] as Any } ?? NSNull()]
    }

    static func buffer(_ image: CGImage, context: CIContext) throws -> CVPixelBuffer {
        var output: CVPixelBuffer?
        let attributes = [kCVPixelBufferIOSurfacePropertiesKey: [:]] as CFDictionary
        guard CVPixelBufferCreate(kCFAllocatorDefault, image.width, image.height,
            kCVPixelFormatType_32BGRA, attributes, &output) == kCVReturnSuccess, let output else {
            throw Failure(message: "Cannot allocate full-source fusion buffer")
        }
        context.render(CIImage(cgImage: image), to: output,
            bounds: CGRect(x: 0, y: 0, width: image.width, height: image.height),
            colorSpace: CGColorSpace(name: CGColorSpace.sRGB))
        return output
    }

    static func main() throws {
        guard CommandLine.arguments.count == 5 else {
            throw Failure(message: "Usage: SubjectFusionValidation photos ground-truth.json output.json expected-detector")
        }
        let directory = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
        let truth = try JSONDecoder().decode(GroundTruth.self,
            from: Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[2])))
        let outputURL = URL(fileURLWithPath: CommandLine.arguments[3])
        let expectedDetector = CommandLine.arguments[4]
        guard truth.images.count == 96, Set(truth.images.map(\.id)).count == 96,
              Set(truth.images.map(\.file_name)).count == 96 else {
            throw Failure(message: "Fusion validation requires all 96 distinct frozen COCO images")
        }
        let renderer = CompositionImageRenderer()
        let analyzer = NativeSubjectAnalysis(renderer: renderer)
        let context = CIContext(options: [.cacheIntermediates: false])
        var rows: [[String: Any]] = []
        for (index, source) in truth.images.enumerated() {
            let row: [String: Any] = try autoreleasepool {
                let file = directory.appendingPathComponent(source.file_name)
                guard let decoded = CGImageSourceCreateWithURL(file as CFURL, nil),
                      let image = CGImageSourceCreateImageAtIndex(decoded, 0, nil),
                      image.width == source.width, image.height == source.height else {
                    throw Failure(message: "Cannot decode exact author source dimensions: \(source.file_name)")
                }
                let pixels = try buffer(image, context: context)
                let started = ProcessInfo.processInfo.systemUptime
                guard let result = analyzer.analyze(pixels, includeSceneSemantics: true) else {
                    throw Failure(message: "Production subject fusion failed: \(source.file_name)")
                }
                let actual = YOLODetectionEngine.shared.activePhotographicModelName
                guard actual == expectedDetector else {
                    throw Failure(message: "Expected \(expectedDetector), executed \(actual ?? "none"): \(source.file_name)")
                }
                let candidates = try result.allCandidates.enumerated().map {
                    try candidate($0.element, rank: $0.offset)
                }
                return ["file": source.file_name, "imageID": source.id,
                    "sourceWidth": image.width, "sourceHeight": image.height,
                    "executedPhotographicDetector": expectedDetector,
                    "scene": result.detectedScene.rawValue,
                    "usedSemanticModel": result.usedSemanticModel,
                    "allFaceCount": result.allFaceRects.count,
                    "allFaceBounds": result.allFaceRects.map(box),
                    "candidates": candidates, "hero": candidates.first.map { $0 as Any } ?? NSNull(),
                    "secondsMac": ProcessInfo.processInfo.systemUptime - started]
            }
            rows.append(row)
            print("Fused recognition \(index + 1)/\(truth.images.count): \(source.file_name); hero=\(row["hero"] ?? NSNull())")
            fflush(stdout)
        }
        let report: [String: Any] = ["images": rows.count, "model": expectedDetector,
            "records": rows,
            "scope": "Production recognition, Vision/YOLO fusion, face association, saliency, hero ranking and coherent groups on all 96 frozen COCO images. Full source dimensions, no expected hero labels. macOS data-only adapters omit iOS UI/filter properties. No composition, physical iPhone or shutter test."]
        try JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]).write(to: outputURL)
        print("PASS: actual production fused recognition completed for all \(rows.count) frozen sources")
    }
}
